contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to call Command with arbitrary target/data and amount. If caller (this) is not Owner,
    // then Command must either revert or not decrease C's balance. If this contract is Owner,
    // then Command may succeed and may decrease balance.
    function run(address target, bytes memory data, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe Owner and balance before
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the call to Command, sending amount wei
        bool cmdReverted;
        c.Command{value: amount}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            cmdReverted = true;
        } else {
            cmdReverted = false;
        }

        // observe balance after and Owner after
        uint balAfter = address(c).balance;
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;

        // General rule: Owner never changes; and if the caller is not Owner then either Command reverted
        // or C's balance did not decrease (i.e., balAfter >= balBefore). If caller is Owner then no restriction on balance change.
        assert(ownerAfter == ownerBefore && (ownerBefore != address(this) ? (cmdReverted || balAfter >= balBefore) : true));
    }

    receive() external payable {}
}

